// gen_planes.cpp — freeze the fixed-seed random projection planes.
//
// genome colouring (genome_color.hpp) and the species SimHash (stats.hpp)
// used to build their fixed random hyperplanes at runtime from
// std::normal_distribution over fixed-seed mt19937s. normal_distribution is
// implementation-defined: libstdc++ (native) and libc++ (Emscripten/wasm)
// produce different planes, so colours and species counts would disagree
// between native and browser builds. This tool prints those planes — as
// generated by THE NATIVE gcc/libstdc++ TOOLCHAIN — as float bit patterns,
// producing src/core/plane_data.hpp. Freezing them keeps colours and the
// species metric byte-identical to every run from <= v0.17.0 AND identical
// across native and wasm builds.
//
// Regenerate (only if STATS_DIM ever changes — which itself breaks
// comparability and deserves a version note):
//   g++ -O2 -std=c++20 -I src tools/gen_planes.cpp -o gen_planes
//   ./gen_planes > src/core/plane_data.hpp
#include <cstdio>
#include <cstring>
#include <cstdint>
#include <random>
#include "core/connectivity.hpp"

static void emit(const char* name, unsigned seed, int rows, int dim) {
    std::mt19937 g(seed);
    std::normal_distribution<float> nd(0.0f, 1.0f);
    printf("inline constexpr uint32_t %s[%d][%d] = {\n", name, rows, dim);
    for (int r = 0; r < rows; ++r) {
        printf("{");
        for (int i = 0; i < dim; ++i) {
            float v = nd(g);
            uint32_t b;
            memcpy(&b, &v, 4);
            printf("0x%08Xu,%s", b, (i % 10 == 9) ? "\n" : "");
        }
        printf("},\n");
    }
    printf("};\n\n");
}

int main() {
    printf("#pragma once\n");
    printf("#include <cstdint>\n");
    printf("#include \"connectivity.hpp\"\n\n");
    printf("// GENERATED by tools/gen_planes.cpp — DO NOT EDIT.\n");
    printf("// Fixed random projection planes as float bit patterns, frozen at v0.18.0\n");
    printf("// from libstdc++'s std::normal_distribution<float>(0,1) over the fixed-seed\n");
    printf("// mt19937s that used to generate them at runtime. Frozen so that (a) genome\n");
    printf("// colours and the species SimHash are identical across native and wasm\n");
    printf("// builds (std::normal_distribution is implementation-defined) and (b) both\n");
    printf("// stay byte-identical to runs from <= v0.17.0.\n");
    printf("// Seeds: colour 0x5EEDC010, SimHash 0xC0FFEE.\n\n");
    printf("static_assert(STATS_DIM == %d,\n"
           "              \"connectivity dimensions changed — regenerate plane_data.hpp \"\n"
           "              \"with tools/gen_planes.cpp (and note the metric break)\");\n\n",
           STATS_DIM);
    const int kHashBits = 16;  // == STATS_HASH_BITS (static_asserted in stats.hpp)
    emit("kGenomeColorPlaneBits", 0x5EEDC010u, 3, STATS_DIM);
    emit("kSimHashPlaneBits", 0xC0FFEEu, kHashBits, STATS_DIM);
    return 0;
}
